module fsm(
    input IN,
    input CLK,
    input RST,
    output reg MATCH
    );

parameter s0 = 0;
parameter s1 = 1;
parameter s2 = 2;
parameter s3 = 3;
parameter s4 = 4;
parameter s5 = 5;

reg [2:0] ST_cr;
reg [2:0] ST_nt;

always @(posedge CLK or posedge RST) begin
    if (~RST) begin
        ST_cr <= s0;
    end
    else begin
        ST_cr <= ST_nt;
    end
end

always @(*) begin
    case (ST_cr)
        s0: if (IN == 0) begin
                ST_nt <= s0;
            end
            else begin
                ST_nt <= s0;
            end
        s1: if (IN == 0) begin
                ST_nt <= s2;
            end
            else begin
                ST_nt <= s1;
            end
        s2: if (IN == 0) begin
                ST_nt <= s3;
            end
            else begin
                ST_nt <= s1;
            end
        s3: if (IN == 0) begin
                ST_nt <= s0;
            end
            else begin
                ST_nt <= s4;
            end
        s4: if (IN == 0) begin
                ST_nt <= s2;
            end
            else begin
                ST_nt <= s5;
            end
        s5: if (IN == 0) begin
                ST_nt <= s2;
            end
            else begin
                ST_nt <= s1;
            end
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (~RST) begin
        MATCH <= 0;
    end
    else begin
        MATCH <= (ST_cr == s4 && IN == 1)? 1:0;
    end
end

endmodule
